import{_ as o,o as t,c as a,a2 as i}from"./chunks/framework.D7WGirly.js";const c=JSON.parse('{"title":"Bento Grids — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"bento-grids-02-how-tos-and-workflows.md","filePath":"bento-grids-02-how-tos-and-workflows.md"}'),n={name:"bento-grids-02-how-tos-and-workflows.md"};function r(s,e,l,d,g,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="bento-grids-—-how-tos-workflows" tabindex="-1">Bento Grids — How-tos &amp; Workflows <a class="header-anchor" href="#bento-grids-—-how-tos-workflows" aria-label="Permalink to &quot;Bento Grids — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Bento Grid workflows</em></p><hr><h2 id="creating-a-bento-grid-from-a-release-note" tabindex="-1">Creating a Bento Grid from a Release Note <a class="header-anchor" href="#creating-a-bento-grid-from-a-release-note" aria-label="Permalink to &quot;Creating a Bento Grid from a Release Note&quot;">​</a></h2><p>This is the most common workflow. If you have an existing Release with Release Notes, this takes about two minutes.</p><ol><li>Navigate to <strong>Bento Grids</strong> in the left-hand navigation.</li><li>Click <strong>New Bento Grid</strong>.</li><li>From the dropdown, select the Release Note you want to use as the source. The dropdown shows Release Notes grouped by their Release.</li><li>A configuration dialog appears. Choose: <ul><li><strong>Aspect ratio</strong> — 16:9 for slides, 4:3 for documents, 1:1 for social sharing</li><li><strong>Output type</strong> — Single image (one full grid) or Presentation (one slide per cell)</li><li><strong>Theme</strong> — Light or Dark</li><li><strong>Tags</strong> — Whether to show category labels on each cell</li><li><strong>Icons</strong> — Whether to show icons on each cell</li></ul></li><li>Confirm. The AI processes the Release Notes content and groups it into cells.</li><li>Review the proposed grouping. Each cell shows a title and description. If a grouping doesn&#39;t make sense, you can adjust it before confirming.</li><li>Confirm the layout. The grid renders.</li><li>Export or save (see below).</li></ol><hr><h2 id="creating-a-bento-grid-from-a-file-upload" tabindex="-1">Creating a Bento Grid from a File Upload <a class="header-anchor" href="#creating-a-bento-grid-from-a-file-upload" aria-label="Permalink to &quot;Creating a Bento Grid from a File Upload&quot;">​</a></h2><p>Use this when your release content lives outside of Lodestone — in a document, a Notion page, or a markdown file.</p><ol><li>Navigate to <strong>Bento Grids</strong> and click <strong>New Bento Grid</strong>.</li><li>Choose the upload option instead of selecting a Release Note.</li><li>Upload your file. Markdown format is recommended; plain text also works.</li><li>Configure the appearance settings (same as above).</li><li>Review and confirm the AI grouping.</li><li>Export or save.</li></ol><p>Grids created from file uploads are stored as standalone grids and are not linked to any Release.</p><hr><h2 id="exporting-a-bento-grid" tabindex="-1">Exporting a Bento Grid <a class="header-anchor" href="#exporting-a-bento-grid" aria-label="Permalink to &quot;Exporting a Bento Grid&quot;">​</a></h2><h3 id="png-single-image" tabindex="-1">PNG (Single Image) <a class="header-anchor" href="#png-single-image" aria-label="Permalink to &quot;PNG (Single Image)&quot;">​</a></h3><p>Exports the entire grid as one image. Best for sharing in emails, Slack, or dropping into a document.</p><h3 id="powerpoint-pptx" tabindex="-1">PowerPoint (.pptx) <a class="header-anchor" href="#powerpoint-pptx" aria-label="Permalink to &quot;PowerPoint (.pptx)&quot;">​</a></h3><p>Exports the grid as a PowerPoint file. In Single Image mode, this produces one slide. In Presentation mode, it produces one slide per cell, which is useful for narrating the release in a meeting.</p><h3 id="google-slides" tabindex="-1">Google Slides <a class="header-anchor" href="#google-slides" aria-label="Permalink to &quot;Google Slides&quot;">​</a></h3><p>Uploads the grid directly to your connected Google account and opens it as a Google Slides presentation. This requires a Google account to be connected via the integration settings.</p><h3 id="html-shareable-link" tabindex="-1">HTML (shareable link) <a class="header-anchor" href="#html-shareable-link" aria-label="Permalink to &quot;HTML (shareable link)&quot;">​</a></h3><p>Generates a responsive, server-rendered HTML snapshot of the Bento Grid and returns a shareable link. Like the Roadmap and Release HTML exports, this produces a <code>/share/...</code> URL rather than downloading a file — anyone with the link can view the grid in a browser without logging in to Lodestone.</p><p>Click the <strong>Export as HTML</strong> option in the grid toolbar to generate. Each generation produces a new URL; previous links remain valid.</p><hr><h2 id="saving-a-bento-grid" tabindex="-1">Saving a Bento Grid <a class="header-anchor" href="#saving-a-bento-grid" aria-label="Permalink to &quot;Saving a Bento Grid&quot;">​</a></h2><p>Once you&#39;re satisfied with a grid, click <strong>Save</strong>. Saved grids:</p><ul><li>Appear in the Bento Grids list under their Release Note name (or as a standalone grid if file-sourced)</li><li>Can be reopened and re-exported at any time</li><li>Show the date they were last updated and the name of the person who created them</li></ul><p>Saving does not lock the grid. You can regenerate it from the same source at any time — for example, after updating the Release Notes.</p><hr><h2 id="viewing-and-managing-existing-bento-grids" tabindex="-1">Viewing and Managing Existing Bento Grids <a class="header-anchor" href="#viewing-and-managing-existing-bento-grids" aria-label="Permalink to &quot;Viewing and Managing Existing Bento Grids&quot;">​</a></h2><p>The Bento Grids index shows two groups:</p><ul><li><strong>Release Note-linked grids</strong> — listed by Release Note name, with the Release name shown below. A &quot;Saved&quot; indicator appears if a grid has been generated and saved. If no grid exists yet for a given Release Note, clicking through starts the creation flow for that note.</li><li><strong>Standalone grids</strong> — listed as file-sourced with the grid name.</li></ul><p>Click <strong>View Grid</strong> on any entry to open it and access export options.</p><hr><h2 id="regenerating-a-bento-grid" tabindex="-1">Regenerating a Bento Grid <a class="header-anchor" href="#regenerating-a-bento-grid" aria-label="Permalink to &quot;Regenerating a Bento Grid&quot;">​</a></h2><p>If your Release Notes change after you&#39;ve saved a grid, you can regenerate it. Open the saved grid and choose to regenerate from the source. This runs the AI grouping again on the updated content and takes you back through the review step.</p><blockquote><p><strong>Note:</strong> Regenerating replaces the previous layout. If you want to preserve the old version, export it before regenerating.</p></blockquote><hr><p><em>Next: Advanced Features &amp; Customization — getting the most from configuration, output types, and export strategies.</em></p>',38)])])}const u=o(n,[["render",r]]);export{c as __pageData,u as default};
